{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Indomethacin, sharing a chloroaromatic/indole and methoxyaryl framework, had absolute F=0.76 in a sustained-release formulation, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Alfuzosin, containing a dimethoxyphenyl-fused aminopyrimidine, had absolute F=49% under fed conditions, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Abecarnil, an indole-containing aromatic ether, had absolute F=39% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alisertib, a high-MW aminopyrimidine/chloroaryl compound, had F=0.671, supporting high bioavailability despite large size.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tenuazonic acid, with methoxyphenyl/chloroaryl/amide features, showed high bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Piritrexim, containing the same 2,4-diaminopyrimidine and dimethoxybenzyl motif, had absolute F=43% in patients, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "2,4-D, a chloroaryloxyacetic acid, showed rapid and complete oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Papaverine, a dimethoxybenzyl heteroaromatic, had absolute F=29%, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Indomethacin conventional capsules had absolute F=0.89, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Doxazosin, a dimethoxyquinazoline aminopyrimidine analogue, had F=69% in elderly subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues, including direct structural relatives with diaminopyrimidine, dimethoxyphenyl, and chloroindole motifs, show absolute oral bioavailability at or above 20% (mostly 29-100%). The physicochemical prior of low F is overridden by this consistent experimental evidence.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the exact query molecule.",
    "High TPSA (145.5) and high molecular weight (535) with unfavorable solubility could still limit absorption.",
    "First-pass metabolism and transporter-mediated efflux for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

